effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  float o = depth * (l - 0.5) * 2.0 * mixAmt;
  float r = texture2DCv(inputImg.texture, uv + vec2(o, 0.0)).r;
  float g = texture2DCv(inputImg.texture, uv).g;
  float b = texture2DCv(inputImg.texture, uv - vec2(o, 0.0)).b;
  vec3 stereo = vec3(r, g, b);
  vec3 holo = vec3(l * 0.12, l * 1.20 + 0.035, l * 1.42 + 0.075) * a;
  float scan = 1.0 - scanlines * (0.5 + 0.5 * sin((uv.y * acScreenSize.y + acTime * speed * 42.0) * 3.1415926));
  float flicker = 0.92 + 0.08 * sin(acTime * 37.0 + uv.y * 4.0);
  vec3 glow = vec3(max(l - 0.52, 0.0) * 0.95) * a;
  vec3 strong = (mix(stereo, holo, cyanTint) + glow) * scan * flicker;
  vec3 finalColor = mix(stereo, clamp(strong, 0.0, 1.0), mixAmt);
  gl_FragColor = vec4(finalColor, a);
}
